using System.Globalization;
using System.Text.Json;
using Duende.IdentityModel.OidcClient.Browser;
namespace UnscRelay.Core;
public sealed record PlainExportReview(Guid ArchiveId,string Name,string ArchiveOwner,long Revision,int Format,string Scope);
public sealed record PlainExportChallenge(Guid Id,string Email,long Revision,DateTimeOffset ExpiresAt);
public sealed partial class CloudAccountClient
{
 public async Task<JsonElement> PlainExportSource(PlainExportReview review,CancellationToken ct){var value=await PortalRead(ArchivePath(review.ArchiveId)+"/vault",ct);if(value.GetProperty("revision").GetInt64()!=review.Revision)throw new OnlineAccessException("La revisione corrente è cambiata. Ripeti il riepilogo.");return value.GetProperty("envelope").Clone();}
 public async Task<PlainExportReview> ReviewPlainExport(Guid archive,CancellationToken ct){var review=await ArchiveRequest<PlainExportReview>(HttpMethod.Get,ArchivePath(archive)+"/plain-export",null,ct);if(review.ArchiveId!=archive||review.Revision is <1 or >9007199254740991||review.Format is not(1 or 2)||review.ArchiveOwner is not{Length:64}||!review.ArchiveOwner.All(char.IsAsciiHexDigit)||review.Name is not{Length:>0 and <=100}||review.Scope!="current")throw new InvalidDataException("Riepilogo esportazione non valido.");return review;}
 public async Task<PlainExportChallenge> BeginPlainExport(PlainExportReview review,IBrowser browser,CancellationToken ct){var proof=await ConfirmSensitive("archive.export",review.ArchiveId.ToString("D"),SensitiveIntentHash("archive.export",review.ArchiveId.ToString("D"),review.Revision.ToString(CultureInfo.InvariantCulture),"current-all"),browser,ct);using var response=await Send(HttpMethod.Post,ArchivePath(review.ArchiveId)+"/plain-export",new{revision=review.Revision},ct,confirmation:proof);var value=await PortalResult(response,ct);var challenge=value.Deserialize<PlainExportChallenge>(VaultSyncCrypto.Json)??throw new InvalidDataException("Conferma esportazione non valida.");if(challenge.Id==Guid.Empty||challenge.Revision!=review.Revision||challenge.ExpiresAt<=DateTimeOffset.UtcNow||challenge.ExpiresAt>DateTimeOffset.UtcNow.AddMinutes(11))throw new InvalidDataException("Conferma esportazione non valida.");return challenge;}
 public async Task<JsonElement> DownloadPlainExport(PlainExportReview review,Guid challenge,string code,CancellationToken ct){if(code.Length>32)throw new ArgumentException("Codice email non valido.");using var response=await Send(HttpMethod.Post,ArchivePath(review.ArchiveId)+"/plain-export/download",new{challengeId=challenge,revision=review.Revision,code},ct);var value=await PortalResult(response,ct);if(value.GetProperty("archiveId").GetGuid()!=review.ArchiveId||value.GetProperty("archiveOwner").GetString()!=review.ArchiveOwner||value.GetProperty("revision").GetInt64()!=review.Revision||value.GetProperty("scope").GetString()!="current")throw new InvalidDataException("La risposta non corrisponde all’esportazione confermata.");var envelope=value.GetProperty("envelope");if(envelope.GetProperty("version").GetInt32()!=review.Format)throw new InvalidDataException("Formato cambiato durante l’esportazione.");return envelope.Clone();}
 public async Task CancelPlainExport(Guid archive,Guid challenge,CancellationToken ct){using var response=await Send(HttpMethod.Post,ArchivePath(archive)+"/plain-export/"+challenge.ToString("D")+"/cancel",null,ct);await PortalResult(response,ct);}
}
